function copyText(t) {
  try { if (MS.copy) { MS.copy(t); return; } } catch (e0) {}
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(t);
      return;
    }
  } catch (e1) {}
  try {
    var ta = document.createElement('textarea');
    ta.value = t;
    ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0;';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    ta.remove();
    return;
  } catch (e2) {}
  MS.log(t);
}
MS.hook('shortcuts', function () {
  var mod = MS.config.get('mod', 'alt');
  var key = MS.config.get('key', 'e');
  return [{
    mod: mod,
    key: key,
    run: function () {
      var arr = MS.media.list('img').concat(MS.media.list('video') || []);
      if (!arr.length) { MS.toast('还没有资源', 'warn'); return; }
      var text = arr.join('\n');
      copyText(text);
      MS.toast('已复制 ' + arr.length + ' 条链接', 'success');
    }
  }];
});
